module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd1 * xs[0] + 8'd3 * xs[1] + 8'd6 * xs[2] + 8'd10 * xs[3] + 8'd15 * xs[4] + 8'd21 * xs[5] + 8'd28 * xs[6] + 8'd36 * xs[7] + 8'd45 * xs[8] + 8'd55 * xs[9] + 8'd66 * xs[10] + 8'd78 * xs[11] + 8'd91 * xs[12] + 8'd105 * xs[13] + 8'd120 * xs[14] + 8'd136 * xs[15] + 8'd153 * xs[16] + 8'd171 * xs[17];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule

